<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import {
  addDigitalLifeFact,
  askDigitalLife,
  deleteDigitalLife,
  deleteDigitalLifeFact,
  enableDigitalLife,
  getDigitalLifeWorkspace,
  getMemorial,
  updateDigitalLifeFactStatus,
  updateDigitalLifeStatus,
  type DigitalLifeAnswer,
  type DigitalLifeFact,
  type DigitalLifeWorkspace,
  type Memorial,
} from '@/api/memorials'

const route = useRoute()
const memorialId = computed(() => String(route.params.id))
const memorial = ref<Memorial | null>(null)
const workspace = ref<DigitalLifeWorkspace | null>(null)
const loading = ref(true)
const busy = ref('')
const error = ref('')
const notice = ref('')
const profileConsent = ref(false)
const textConsent = ref(false)
const question = ref('')
const answer = ref<DigitalLifeAnswer | null>(null)
const fact = reactive<Omit<DigitalLifeFact, 'id' | 'profileId' | 'createdAt' | 'updatedAt'>>({ factType: 'HABIT', statement: '', sourceType: 'USER_NOTE', sourceLabel: '我亲自补充', verificationStatus: 'PENDING' })

const confirmedFacts = computed(() => workspace.value?.facts.filter((item) => item.verificationStatus === 'CONFIRMED') ?? [])
const pendingFacts = computed(() => workspace.value?.facts.filter((item) => item.verificationStatus === 'PENDING') ?? [])

async function load() { loading.value = true; error.value = ''; try { const [current, currentWorkspace] = await Promise.all([getMemorial(memorialId.value), getDigitalLifeWorkspace(memorialId.value)]); memorial.value = current; workspace.value = currentWorkspace } catch (caught) { error.value = caught instanceof Error ? caught.message : '暂时无法读取数字记忆档案。' } finally { loading.value = false } }
async function enable() { if (!profileConsent.value || !textConsent.value) { error.value = '请分别确认资料整理和文本处理授权。'; return } busy.value = 'enable'; error.value = ''; try { workspace.value = await enableDigitalLife(memorialId.value); notice.value = '数字记忆档案已经建立。系统只导入待确认资料，不会编造新的经历。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '暂时无法建立档案。' } finally { busy.value = '' } }
async function addFact() { busy.value = 'fact'; error.value = ''; try { const created = await addDigitalLifeFact(memorialId.value, { ...fact, statement: fact.statement.trim(), sourceLabel: fact.sourceLabel.trim() }); workspace.value?.facts.push(created); Object.assign(fact, { factType: 'HABIT', statement: '', sourceType: 'USER_NOTE', sourceLabel: '我亲自补充', verificationStatus: 'PENDING' }); notice.value = '这条资料先被标记为待确认。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '这条资料没有保存。' } finally { busy.value = '' } }
async function setFactStatus(item: DigitalLifeFact, status: DigitalLifeFact['verificationStatus']) { busy.value = item.id; error.value = ''; try { const updated = await updateDigitalLifeFactStatus(memorialId.value, item.id, status); if (workspace.value) workspace.value.facts = workspace.value.facts.map((entry) => entry.id === updated.id ? updated : entry); notice.value = status === 'CONFIRMED' ? '这条资料已确认，可以成为记忆问答的来源。' : '这条资料不会进入记忆问答。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '状态没有更新。' } finally { busy.value = '' } }
async function removeFact(item: DigitalLifeFact) { if (!window.confirm(`删除“${item.statement}”吗？`)) return; busy.value = item.id; try { await deleteDigitalLifeFact(memorialId.value, item.id); if (workspace.value) workspace.value.facts = workspace.value.facts.filter((entry) => entry.id !== item.id); notice.value = '这条数字记忆已经删除。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '删除没有完成。' } finally { busy.value = '' } }
async function ask() { busy.value = 'question'; error.value = ''; answer.value = null; try { answer.value = await askDigitalLife(memorialId.value, question.value.trim()) } catch (caught) { error.value = caught instanceof Error ? caught.message : '暂时无法回答。' } finally { busy.value = '' } }
async function changeStatus(status: 'ACTIVE' | 'PAUSED' | 'ARCHIVED') { busy.value = 'status'; error.value = ''; try { workspace.value = await updateDigitalLifeStatus(memorialId.value, status); notice.value = status === 'ACTIVE' ? '数字记忆档案已恢复。' : status === 'PAUSED' ? '数字记忆档案已暂停，不会处理新的问答。' : '数字记忆档案已封存。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '状态没有更新。' } finally { busy.value = '' } }
async function erase() { if (!window.confirm('删除后，数字生命档案、事实记录和授权状态会立即清除，无法恢复。确定继续吗？')) return; busy.value = 'delete'; try { await deleteDigitalLife(memorialId.value); workspace.value = workspace.value ? { ...workspace.value, profile: null, facts: [] } : null; answer.value = null; notice.value = '数字记忆档案已经永久清除。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '删除没有完成。' } finally { busy.value = '' } }
onMounted(load)
</script>

<template>
  <main class="digital-life-page section-narrow">
    <div v-if="loading" class="account-empty">正在检查数字记忆档案…</div>
    <template v-else-if="memorial && workspace">
      <header class="digital-intro"><div><p class="eyebrow">{{ memorial.petName }} 的数字记忆档案</p><h1>让资料帮助回想，<br />不替代 TA。</h1><p>这里不是“复活”或人格扮演。它只是把你授权、确认过的记忆整理成可追溯的档案。</p></div><RouterLink class="button button-quiet" :to="`/editor/${memorialId}/ritual`">回到仪式中心</RouterLink></header>
      <p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-success" role="status">{{ notice }}</p>
      <aside class="ethics-note"><span aria-hidden="true">◎</span><p>{{ workspace.ethicsNotice }}</p></aside>
      <section v-if="!workspace.profile" class="consent-panel"><div><p class="eyebrow">第一阶段 · 数字记忆档案</p><h2>{{ workspace.profileAvailable ? '先建立清楚的授权边界。' : '这项能力已预留，等待会员权益开启。' }}</h2><p>系统只会整理生命指纹中已有的文字为“待确认资料”。你可以逐条确认、拒绝或永久删除。</p></div><template v-if="workspace.profileAvailable"><label><input v-model="profileConsent" type="checkbox" />我确认拥有并愿意授权这些纪念资料用于建立私密数字记忆档案。</label><label><input v-model="textConsent" type="checkbox" />我同意平台按说明处理我主动授权的文字资料，并可随时撤回。</label><button class="button" :disabled="busy === 'enable'" @click="enable">{{ busy === 'enable' ? '正在建立…' : '建立数字记忆档案' }}</button></template><RouterLink v-else class="button button-quiet" to="/pricing">查看高级会员权益</RouterLink></section>
      <template v-else>
        <section class="digital-status"><div><p class="eyebrow">授权状态</p><h2>{{ workspace.profile.status === 'ACTIVE' ? '档案正在等待你的确认' : workspace.profile.status === 'PAUSED' ? '档案已暂停' : '档案已封存' }}</h2><p>已确认 {{ confirmedFacts.length }} 条资料，待确认 {{ pendingFacts.length }} 条。只有已确认资料才可能进入问答。</p></div><div class="status-actions"><button v-if="workspace.profile.status !== 'ACTIVE'" class="button" :disabled="busy === 'status'" @click="changeStatus('ACTIVE')">恢复使用</button><button v-else class="button button-quiet" :disabled="busy === 'status'" @click="changeStatus('PAUSED')">暂停档案</button><button class="text-button danger" :disabled="busy === 'delete'" @click="erase">永久删除</button></div></section>
        <section class="facts-section"><div class="section-title"><div><p class="eyebrow">可追溯资料</p><h2>每句话都要知道从哪里来。</h2></div><p>系统不会凭空补写经历。待确认资料不会参与问答。</p></div><form class="fact-form" @submit.prevent="addFact"><label>资料类型<select v-model="fact.factType"><option value="HABIT">习惯</option><option value="TRAIT">性格</option><option value="PREFERENCE">偏好</option><option value="RELATION">关系</option><option value="EVENT">事件</option></select></label><label>来源<select v-model="fact.sourceType"><option value="USER_NOTE">我亲自补充</option><option value="LIFE_DETAIL">生命指纹</option><option value="ARCHIVE_ENTRY">生命档案</option><option value="TIMELINE">时间线</option></select></label><label>来源说明<input v-model="fact.sourceLabel" required maxlength="120" /></label><label class="wide">这条真实资料<textarea v-model="fact.statement" required maxlength="500" rows="3" placeholder="例如：饭前会先把水碗轻轻推到墙边。"></textarea></label><button class="button" :disabled="busy === 'fact'">{{ busy === 'fact' ? '正在保存…' : '加入待确认资料' }}</button></form><div class="fact-columns"><section><h3>待确认</h3><article v-for="item in pendingFacts" :key="item.id"><small>{{ item.sourceLabel }}</small><p>{{ item.statement }}</p><div><button class="text-button" :disabled="busy === item.id" @click="setFactStatus(item, 'CONFIRMED')">确认真实</button><button class="text-button" :disabled="busy === item.id" @click="setFactStatus(item, 'REJECTED')">不采用</button><button class="text-button danger" :disabled="busy === item.id" @click="removeFact(item)">删除</button></div></article><p v-if="!pendingFacts.length" class="empty">没有待确认资料。</p></section><section><h3>已确认</h3><article v-for="item in confirmedFacts" :key="item.id"><small>{{ item.sourceLabel }}</small><p>{{ item.statement }}</p><div><button class="text-button" :disabled="busy === item.id" @click="setFactStatus(item, 'REJECTED')">撤回确认</button><button class="text-button danger" :disabled="busy === item.id" @click="removeFact(item)">删除</button></div></article><p v-if="!confirmedFacts.length" class="empty">确认后，资料才会出现在这里。</p></section></div></section>
        <section class="qa-section"><div><p class="eyebrow">第二阶段 · 记忆问答</p><h2>问资料，不问“TA 在哪里”。</h2><p>回答使用第三人称，并显示它引用的资料来源。没有资料时，它会明确说不知道。</p></div><form v-if="workspace.qaAvailable && workspace.profile.status === 'ACTIVE'" @submit.prevent="ask"><label>想问什么？<input v-model="question" required maxlength="240" placeholder="例如：TA 最喜欢待在哪里？" /></label><button class="button" :disabled="busy === 'question'">{{ busy === 'question' ? '正在整理资料…' : '从记忆中查找' }}</button></form><RouterLink v-else class="button button-quiet" to="/pricing">{{ workspace.qaAvailable ? '档案暂停中' : '问答需要时光珍藏会员' }}</RouterLink><article v-if="answer" class="answer-card"><p>{{ answer.answer }}</p><ul v-if="answer.citations.length"><li v-for="citation in answer.citations" :key="`${citation.sourceType}-${citation.sourceLabel}`"><strong>{{ citation.sourceLabel }}</strong><span>{{ citation.statement }}</span></li></ul><small>{{ answer.safetyNotice }}</small></article></section>
      </template>
      <section class="provider-section"><p class="eyebrow">未来能力的开放状态</p><h2>声音与形象不会悄悄上线。</h2><div><article v-for="provider in workspace.providerStatuses" :key="provider.capability"><strong>{{ provider.capability === 'MEMORY_QA' ? '记忆问答' : provider.capability === 'VOICE_REPLICA' ? '声音复刻' : '数字形象' }}</strong><span>{{ provider.status === 'LOCAL_MOCK' ? '本地模拟中' : '尚未开放' }}</span><p>{{ provider.notice }}</p></article></div></section>
    </template>
  </main>
</template>

<style scoped>
.digital-life-page{padding-block:clamp(2rem,5vw,5rem)}.digital-intro{display:flex;justify-content:space-between;align-items:end;gap:2rem;margin-bottom:2rem}.digital-intro h1{margin:.45rem 0 1rem;font:clamp(42px,6vw,76px)/1.05 var(--font-serif)}.digital-intro p:last-child{max-width:620px;color:var(--muted);line-height:1.85}.ethics-note{display:flex;gap:1rem;padding:1rem 1.2rem;margin-bottom:2.5rem;border:1px solid color-mix(in srgb,var(--primary) 35%,var(--border));border-radius:12px;background:color-mix(in srgb,var(--primary) 8%,transparent);color:var(--muted);line-height:1.7}.ethics-note span{color:var(--primary);font-size:1.2rem}.ethics-note p{margin:0}.consent-panel{display:grid;gap:1rem;max-width:860px;padding:clamp(28px,5vw,60px);border:1px solid var(--border);border-radius:24px;background:linear-gradient(145deg,color-mix(in srgb,var(--surface) 88%,var(--primary)),var(--surface))}.consent-panel h2,.digital-status h2,.section-title h2,.qa-section h2,.provider-section h2{margin:.45rem 0;font:clamp(30px,4vw,52px)/1.18 var(--font-serif)}.consent-panel>div>p:last-child,.digital-status p,.section-title>p,.qa-section>div>p:last-child{max-width:600px;color:var(--muted);line-height:1.8}.consent-panel label{display:flex;gap:.65rem;align-items:start;max-width:700px;line-height:1.65}.consent-panel .button{justify-self:start}.digital-status{display:flex;justify-content:space-between;align-items:end;gap:2rem;padding:2rem 0;border-bottom:1px solid var(--border)}.status-actions{display:flex;align-items:center;gap:.8rem;flex-wrap:wrap}.danger{color:#c98585}.facts-section{margin-top:clamp(3rem,7vw,6rem)}.section-title{display:grid;grid-template-columns:minmax(260px,.9fr) minmax(0,1.1fr);gap:2rem;align-items:end}.section-title>p{margin:0}.fact-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin:2rem 0}.fact-form label,.qa-section label{display:grid;gap:.45rem;color:var(--muted);font-size:.88rem}.fact-form select,.fact-form input,.fact-form textarea,.qa-section input{width:100%;color:var(--text)}.fact-form .wide,.fact-form>.button{grid-column:1/-1}.fact-form>.button{justify-self:start}.fact-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.fact-columns section{padding:1.2rem;border:1px solid var(--border);border-radius:16px;background:color-mix(in srgb,var(--surface) 73%,transparent)}.fact-columns h3{margin:0 0 1rem;font:1.4rem var(--font-serif)}.fact-columns article{padding:1rem 0;border-top:1px solid color-mix(in srgb,var(--border) 72%,transparent)}.fact-columns article small{color:var(--primary)}.fact-columns article p{margin:.45rem 0;color:var(--muted);line-height:1.65}.fact-columns article div{display:flex;gap:.8rem;flex-wrap:wrap}.empty{color:var(--muted)}.qa-section{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.2fr);gap:clamp(30px,7vw,100px);margin-top:clamp(4rem,8vw,8rem);padding:clamp(26px,5vw,56px);border:1px solid color-mix(in srgb,var(--primary) 28%,var(--border));border-radius:24px;background:radial-gradient(circle at 80% 20%,rgb(225 191 126 / 14%),transparent 30%),var(--surface)}.qa-section form{display:grid;align-content:start;gap:1rem}.qa-section form .button{justify-self:start}.answer-card{grid-column:1/-1;padding-top:2rem;border-top:1px solid var(--border)}.answer-card>p{margin:0 0 1.25rem;font:clamp(20px,2.5vw,30px)/1.7 var(--font-serif)}.answer-card ul{display:grid;gap:.5rem;padding:0;list-style:none}.answer-card li{display:grid;gap:.2rem;padding:.8rem;border-left:2px solid var(--primary);background:color-mix(in srgb,var(--canvas) 48%,transparent)}.answer-card li span,.answer-card small{color:var(--muted);line-height:1.65}.answer-card small{display:block;margin-top:1rem}.provider-section{margin-top:4rem}.provider-section>div{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;border:1px solid var(--border);background:var(--border)}.provider-section article{padding:1.25rem;background:var(--canvas)}.provider-section strong,.provider-section span{display:block}.provider-section span{margin-top:.45rem;color:var(--primary);font-size:.8rem}.provider-section p{margin:.85rem 0 0;color:var(--muted);line-height:1.65;font-size:.88rem}@media(max-width:760px){.digital-intro,.digital-status,.section-title,.qa-section{display:grid}.fact-form,.fact-columns,.provider-section>div{grid-template-columns:1fr}.status-actions{justify-content:start}}@media(max-width:480px){.fact-form{grid-template-columns:1fr}.ethics-note{align-items:start}}
</style>
